import{_ as e,o as i,c as a,al as t}from"./chunks/framework.7vp1BMOE.js";const u=JSON.parse('{"title":"macOS Development Environment","description":"","frontmatter":{},"headers":[],"relativePath":"uk/dev_setup/dev_env_mac.md","filePath":"uk/dev_setup/dev_env_mac.md"}'),n={name:"uk/dev_setup/dev_env_mac.md"};function o(l,s,p,d,h,r){return i(),a("div",null,[...s[0]||(s[0]=[t(`<h1 id="macos-development-environment" tabindex="-1">macOS Development Environment <a class="header-anchor" href="#macos-development-environment" aria-label="Permalink to &quot;macOS Development Environment&quot;">​</a></h1><p>The following instructions set up a PX4 development environment on macOS. Це середовище може бути використане для збірки PX4 для:</p><ul><li>Pixhawk та іншого апаратного забезпечення на основі NuttX</li><li><a href="./../sim_gazebo_gz/">Gazebo Simulation</a> (Gazebo Harmonic)</li></ul><p>It works on both Intel and Apple Silicon Macs.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>This setup is supported by the PX4 dev team. To build for <a href="./../dev_setup/dev_env#supported-targets">other targets</a> you will need to use a <a href="./../dev_setup/dev_env#supported-targets">different OS</a> or an <a href="./../advanced/community_supported_dev_env">unsupported development environment</a>.</p></div><h2 id="development-environment-setup" tabindex="-1">Development Environment Setup <a class="header-anchor" href="#development-environment-setup" aria-label="Permalink to &quot;Development Environment Setup&quot;">​</a></h2><h3 id="вимоги" tabindex="-1">Вимоги <a class="header-anchor" href="#вимоги" aria-label="Permalink to &quot;Вимоги&quot;">​</a></h3><ol><li><p><strong>Install Xcode Command Line Tools</strong> — provides <code>git</code>, <code>make</code>, and the Apple <code>clang</code> compiler:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xcode-select</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --install</span></span></code></pre></div></li><li><p><strong>Install Homebrew</strong> by following the <a href="https://brew.sh" target="_blank" rel="noreferrer">installation instructions</a>.</p></li><li><p><strong>Increase the open-file limit.</strong> The PX4 build opens many files simultaneously and the macOS default limit (256) is too low — you may see <code>&quot;LD: too many open files&quot;</code> errors without this.</p><p>Add the following line to your shell startup file so it applies to every new terminal session. macOS defaults to <strong>zsh</strong> since Catalina, so add it to <code>~/.zshrc</code> (use <code>~/.bashrc</code> if you use bash):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;ulimit -S -n 2048&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.zshrc</span></span></code></pre></div><p>Then <strong>open a new terminal</strong> (or run <code>source ~/.zshrc</code>) for the change to take effect.</p></li><li><p><strong>Ensure Python 3 is available.</strong> Some PX4 build scripts require <code>python3</code> and <code>pip3</code> to be in your <code>PATH</code>. The Xcode Command Line Tools include Python 3 by default.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If you need to install or manage a different Python version, we recommend <a href="https://github.com/pyenv/pyenv" target="_blank" rel="noreferrer">pyenv</a>, which lets you set global and per-directory Python versions.</p></div></li></ol><p>:::</p><h3 id="install-development-tools" tabindex="-1">Install Development Tools <a class="header-anchor" href="#install-development-tools" aria-label="Permalink to &quot;Install Development Tools&quot;">​</a></h3><ol><li><p><strong>Download PX4 Source Code:</strong></p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/PX4/PX4-Autopilot.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PX4-Autopilot</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> submodule</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --recursive</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span></span></code></pre></div></li><li><p><strong>Install development environment libraries</strong> from the <a href="https://github.com/PX4/PX4-Autopilot/blob/main/Tools/setup/macos.sh" target="_blank" rel="noreferrer">macos.sh</a> helper script:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./Tools/setup/macos.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --sim-tools</span></span></code></pre></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The setup script creates a Python virtual environment at <code>.venv</code> in the repo root and installs all Python dependencies into it. This keeps PX4&#39;s Python requirements isolated from your system Python and avoids conflicts with Homebrew&#39;s externally-managed Python.</p><p>Activate it before building:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .venv/bin/activate</span></span></code></pre></div><p>You&#39;ll need to re-run this command in each new terminal session. To activate it automatically when you <code>cd</code> into the repo, consider a tool like <a href="https://direnv.net/" target="_blank" rel="noreferrer">direnv</a> or add the activation to your <code>~/.zshrc</code>.</p></div></li></ol><p>:::</p><p>This installs:</p><ul><li><strong>Toolchain packages</strong> from the <code>osx-cross/arm</code> and <code>PX4/px4</code> Homebrew taps — ARM cross-compiler (<code>arm-gcc-bin@13</code>), <code>cmake</code>, <code>ninja</code>, <code>ccache</code>, <code>fastdds</code>, <code>genromfs</code>, <code>kconfig-frontends</code>, and other build tools</li><li><strong>Python packages</strong> from <code>requirements.txt</code></li><li><strong><code>px4-sim</code></strong> (via <code>--sim-tools</code>) — Gazebo Harmonic simulation (<code>gz-harmonic</code>) and related tools</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Omit <code>--sim-tools</code> if you only need to build for NuttX hardware and don&#39;t need simulation.</p><p>Use <code>--reinstall</code> to force reinstallation of all Homebrew formulas (useful if something is broken).</p></div><h3 id="gazebo-simulation" tabindex="-1">Gazebo Simulation <a class="header-anchor" href="#gazebo-simulation" aria-label="Permalink to &quot;Gazebo Simulation&quot;">​</a></h3><p>The <code>--sim-tools</code> flag installs the <code>px4-sim</code> Homebrew formula, which pulls in Gazebo Harmonic.</p><p>If you skipped <code>--sim-tools</code> during initial setup and want to add simulation later:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PX4/px4</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4-sim</span></span></code></pre></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Gazebo requires <strong>XQuartz</strong> for display on macOS. If you don&#39;t already have it installed:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cask</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xquartz</span></span></code></pre></div><p>You may need to log out and back in after installing XQuartz.</p></div><h3 id="verify-installation" tabindex="-1">Verify Installation <a class="header-anchor" href="#verify-installation" aria-label="Permalink to &quot;Verify Installation&quot;">​</a></h3><p>After installation, verify the key tools are available:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># NuttX cross-compiler (from arm-gcc-bin@13)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arm-none-eabi-gcc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Build tools</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ninja</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Gazebo (if --sim-tools was used)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sim</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --versions</span></span></code></pre></div><p>Quick smoke test — build and run a simulation target:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gz_x500</span></span></code></pre></div><p>If everything is set up correctly, this will build PX4 SITL and launch a Gazebo simulation with the x500 quadcopter.</p><h2 id="наступні-кроки" tabindex="-1">Наступні кроки <a class="header-anchor" href="#наступні-кроки" aria-label="Permalink to &quot;Наступні кроки&quot;">​</a></h2><p>Після того, як ви закінчите налаштування інструментів командного рядка:</p><ul><li><p>Install <a href="./../dev_setup/vscode">VSCode</a> (if you prefer using an IDE to the command line).</p></li><li><p>Install the <a href="./../dev_setup/qgc_daily_build">QGroundControl Daily Build</a></p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The <em>daily build</em> includes development tools that are hidden in release builds. Вона також може надати доступ до нових функцій PX4, які ще не підтримуються в релізних збірках.</p></div></li></ul><p>:::</p><ul><li>Continue to the <a href="./../dev_setup/building_px4">build instructions</a>.</li></ul>`,31)])])}const k=e(n,[["render",o]]);export{u as __pageData,k as default};
